import itertools
import json

# Propositional enumeration over a single child/parent situation.
# Variables: hug, loved, low_gh, want_tall, can_promote, tall, hugged_more
VARS = ["hug", "loved", "low_gh", "want_tall", "can_promote", "tall", "hugged_more"]
WORLDS = [dict(zip(VARS, bits)) for bits in itertools.product([False, True], repeat=len(VARS))]

def premises(w):
    p1 = (not w["loved"]) or w["low_gh"]        # not loved -> low growth hormone
    p2 = (not w["want_tall"]) or w["hug"]       # want to grow taller -> hug often
    return p1 and p2

models = [w for w in WORLDS if premises(w)]

options = {
    "A": lambda w: w["can_promote"],                   # parents can promote hugs to grow taller
    "B": lambda w: (not w["hug"]) or (not w["loved"]), # not hugging often -> not loving
    "D": lambda w: (not w["tall"]) or w["hugged_more"],# tall -> more hugged than short
}

def inferable(opt):
    return all(opt(w) for w in models)

# Option C: some psychological state (feeling loved) affects a physical state (GH secretion).
# Check for a dependence: two premise-consistent worlds identical except 'loved', differing in 'low_gh'.
def psych_affects_physical():
    for w in models:
        flipped = dict(w, loved=not w["loved"])
        if premises(flipped) and flipped["low_gh"] != w["low_gh"]:
            return True
    return False

results = {k: inferable(f) for k, f in options.items()}
results["C"] = psych_affects_physical()

final = [k for k in sorted(results) if results[k]]
answer = final[0] if len(final) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "models_satisfying_premises": len(models),
        "inferable": results,
    },
}, separators=(",", ":")))
